CREATE TABLE IF NOT EXISTS metadata(key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tractate(id TEXT PRIMARY KEY, label TEXT NOT NULL, hebrew TEXT NOT NULL, sequence INTEGER NOT NULL, first_daf INTEGER NOT NULL, first_amud TEXT NOT NULL, last_daf INTEGER NOT NULL, last_amud TEXT NOT NULL, source_tractate TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS page(id TEXT PRIMARY KEY, tractate TEXT NOT NULL REFERENCES tractate(id), daf INTEGER NOT NULL, amud TEXT NOT NULL, sequence INTEGER NOT NULL UNIQUE, edition TEXT NOT NULL, source_url TEXT NOT NULL, physical_page INTEGER, source_metadata TEXT, asset_path TEXT, source_sha TEXT, width REAL, height REAL, acquisition_state TEXT NOT NULL DEFAULT 'pending', extraction_state TEXT NOT NULL DEFAULT 'pending', error TEXT, modified_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS page_revision(id TEXT PRIMARY KEY, page_id TEXT NOT NULL REFERENCES page(id), source_sha TEXT NOT NULL, geometry_path TEXT NOT NULL, vector_path TEXT, extractor_revision TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS region(id TEXT PRIMARY KEY, page_revision TEXT NOT NULL REFERENCES page_revision(id), kind TEXT NOT NULL, bounds_json TEXT NOT NULL, reading_order INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS occurrence(id TEXT PRIMARY KEY, page_id TEXT NOT NULL REFERENCES page(id), page_revision TEXT NOT NULL REFERENCES page_revision(id), region_id TEXT NOT NULL REFERENCES region(id), line_id TEXT NOT NULL, text TEXT NOT NULL, normalized TEXT NOT NULL, geometry_json TEXT NOT NULL, reading_order INTEGER NOT NULL, transcription_state TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1);
CREATE INDEX IF NOT EXISTS occurrence_page ON occurrence(page_id, active, reading_order);
CREATE VIRTUAL TABLE IF NOT EXISTS printed_text USING fts5(occurrence_id UNINDEXED,page_id UNINDEXED,text,normalized,tokenize='unicode61 remove_diacritics 2');
CREATE TRIGGER IF NOT EXISTS occurrence_insert AFTER INSERT ON occurrence WHEN new.active=1 BEGIN INSERT INTO printed_text(occurrence_id,page_id,text,normalized) VALUES(new.id,new.page_id,new.text,new.normalized); END;
CREATE TRIGGER IF NOT EXISTS occurrence_delete AFTER DELETE ON occurrence BEGIN DELETE FROM printed_text WHERE occurrence_id=old.id; END;
CREATE TRIGGER IF NOT EXISTS occurrence_update AFTER UPDATE ON occurrence BEGIN DELETE FROM printed_text WHERE occurrence_id=old.id; INSERT INTO printed_text(occurrence_id,page_id,text,normalized) SELECT new.id,new.page_id,new.text,new.normalized WHERE new.active=1; END;
CREATE TABLE IF NOT EXISTS source_issue(id INTEGER PRIMARY KEY, page_id TEXT REFERENCES page(id), kind TEXT NOT NULL, evidence_json TEXT NOT NULL, resolved INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS font_mapping(font_fingerprint TEXT NOT NULL, glyph INTEGER NOT NULL, unicode TEXT NOT NULL, provenance_json TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1, PRIMARY KEY(font_fingerprint,glyph));
CREATE TABLE IF NOT EXISTS correction(id TEXT PRIMARY KEY, page_id TEXT NOT NULL REFERENCES page(id), base_revision TEXT NOT NULL, kind TEXT NOT NULL, payload_json TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS anchor_mapping(correction_id TEXT NOT NULL REFERENCES correction(id), old_id TEXT NOT NULL REFERENCES occurrence(id), new_id TEXT REFERENCES occurrence(id), status TEXT NOT NULL, PRIMARY KEY(correction_id,old_id));
CREATE TABLE IF NOT EXISTS dictionary_entry(id TEXT PRIMARY KEY, headword TEXT NOT NULL, normalized TEXT NOT NULL, ordinal INTEGER NOT NULL, raw_json TEXT NOT NULL, html TEXT NOT NULL, revision TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS entry_headword ON dictionary_entry(normalized);
CREATE VIRTUAL TABLE IF NOT EXISTS dictionary_text USING fts5(entry_id UNINDEXED,headword,content,tokenize='unicode61 remove_diacritics 2');
CREATE TABLE IF NOT EXISTS sense(id TEXT PRIMARY KEY, entry_id TEXT NOT NULL REFERENCES dictionary_entry(id), parent_id TEXT REFERENCES sense(id), ordinal INTEGER NOT NULL, definition_html TEXT NOT NULL, grammar_json TEXT NOT NULL, raw_json TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS sense_entry ON sense(entry_id,ordinal);
CREATE TABLE IF NOT EXISTS dictionary_reference(id TEXT PRIMARY KEY, entry_id TEXT NOT NULL REFERENCES dictionary_entry(id), target_text TEXT NOT NULL, target_id TEXT REFERENCES dictionary_entry(id), provenance_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS dictionary_material(id TEXT PRIMARY KEY, source_url TEXT NOT NULL, source_sha TEXT NOT NULL, content TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS annotation(occurrence_id TEXT PRIMARY KEY REFERENCES occurrence(id), head_revision INTEGER NOT NULL DEFAULT 0, modified_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS annotation_revision(occurrence_id TEXT NOT NULL REFERENCES occurrence(id), revision INTEGER NOT NULL, parent_revision INTEGER NOT NULL, text TEXT NOT NULL, direction TEXT NOT NULL CHECK(direction IN ('auto','ltr','rtl')), deleted INTEGER NOT NULL DEFAULT 0, conflict INTEGER NOT NULL DEFAULT 0, operation_id TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(occurrence_id,revision));
CREATE TABLE IF NOT EXISTS operation(id TEXT PRIMARY KEY, kind TEXT NOT NULL, payload_sha TEXT NOT NULL, result_json TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS bookmark(page_id TEXT PRIMARY KEY REFERENCES page(id), occurrence_id TEXT REFERENCES occurrence(id), label TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS preference(key TEXT PRIMARY KEY, value_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS job(id TEXT PRIMARY KEY, kind TEXT NOT NULL, state TEXT NOT NULL, completed INTEGER NOT NULL DEFAULT 0, total INTEGER, detail_json TEXT NOT NULL DEFAULT '{}', updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
